# ПИ-регулятор на Q15 для Cortex-M0 (soft-float)

## 1. Умножение Q15 и насыщающий сумматор

**Умножение:** `int16_t × int16_t → int32_t`, сдвиг на 15 вправо. На M0 нет `SMULL`/`SMLAL`, но компилятор транслирует `(int32_t)a * b >> 15` в вызов `__aeabi_lmul` + сдвиг — это ~20–40 циклов вместо ~150 у `__aeabi_fmul`.

**Переполнение интегратора — да, нужен насыщающий сумматор.** Без него windup убьёт регулятор быстрее, чем float съедал бюджет.

```c
#include <stdint.h>

// Q15: 1.0 = 0x7FFF, -1.0 = 0x8000
typedef int16_t q15_t;
typedef int32_t q31_t;

static inline q15_t q15_mul(q15_t a, q15_t b) {
    // Результат в Q30, сдвигаем к Q15
    // Округление: добавляем 0x4000 перед сдвигом
    q31_t prod = (q31_t)a * (q31_t)b;
    return (q15_t)((prod + 0x4000) >> 15);
}

static inline q15_t q15_sat_add(q15_t a, q15_t b) {
    q31_t sum = (q31_t)a + (q31_t)b;
    if (sum > 0x7FFF)  return 0x7FFF;
    if (sum < -0x8000) return (q15_t)0x8000;
    return (q15_t)sum;
}

// Насыщающее сложение для интегратора (Q31 аккумулятор)
static inline q31_t q31_sat_add(q31_t a, q31_t b) {
    q31_t sum = a + b;
    // Overflow detection: оба одного знака, результат другого
    if (((a ^ b) >= 0) && ((a ^ sum) < 0)) {
        return (a >= 0) ? 0x7FFFFFFF : (q31_t)0x80000000;
    }
    return sum;
}
```

**Почему Q31 для интегратора:** P-слагаемое помещается в Q15, но I-слагаемое накапливается. Если использовать Q15-аккумулятор, он переполнится за десятки итераций при ненулевой ошибке. Держите интегратор в Q31, а выход приводите к Q15.

---

## 2. Масштабирование уставки 0..1000 и защита от windup

**Проблема:** Q15 представляет [-1.0, +0.99997]. Уставка 0..1000 не влезает напрямую.

**Решение:** нормализуйте всё к диапазону [0, 1.0] или [-1.0, 1.0] через масштабный коэффициент.

```
SCALE = 1000  (или макс. значение датчика)
error_q15 = (setpoint - measured) * 32767 / SCALE
```

Но деление на M0 дорогое. Замените на умножение: `32767 / 1000 ≈ 32.767 ≈ 33`. Точнее — используйте Q16 множитель:

```c
#define SENSOR_MAX      1000
// Коэффициент перевода: 32767 / 1000 ≈ 32.767
// В Q15: 32.767 нельзя (больше 1). Используем Q6.9 или просто int32.
// Проще: работаем в единицах "проценты × 327.67"

// Практический подход: ошибка в физических единицах, 
// коэффициенты Kp/Ki уже включают масштаб.

static inline q15_t error_to_q15(int16_t setpoint_raw, int16_t measured_raw) {
    int32_t err = (int32_t)setpoint_raw - (int32_t)measured_raw;
    // err ∈ [-1000, +1000], нужно → [-32767, +32767]
    // err * 32767 / 1000 = err * 32 + err * 767/1000 ≈ err * 33 (грубо)
    // Точно: умножить на 32767, разделить на 1000
    // На M0 без делителя: err * 131 (≈32767/250) >> 2, 
    // или предвычислить таблицу, или:
    int32_t scaled = (err * 32767) / SENSOR_MAX;  
    // ^ деление на константу компилятор превратит в mul+shift

    if (scaled > 0x7FFF)  scaled = 0x7FFF;
    if (scaled < -0x8000) scaled = -0x8000;
    return (q15_t)scaled;
}
```

**Защита интегратора от windup (clamping):**

```c
#define I_LIMIT_Q31  ((q31_t)(0.8f * 32767.0f * 32768.0f))  // 80% от макс

// Вычисляется один раз при настройке:
// I_LIMIT_Q31 = (int32_t)(I_MAX_FRACTION * 2147483647.0)
// где I_MAX_FRACTION = 0.8 — интегратор не может занять больше 80% выхода
```

**Полный цикл ПИ:**

```c
typedef struct {
    q15_t kp;           // Q15: 0.5 = 16384
    q15_t ki;           // Q15, уже включает dt (ki_real * dt * 32767)
    q31_t integrator;   // Q31 аккумулятор
    q15_t i_limit;      // Предел интегратора в Q15 (приводится к Q31 при сравнении)
    q15_t out_min;      // Ограничение выхода
    q15_t out_max;
} pi_q15_t;

q15_t pi_update(pi_q15_t *ctx, q15_t error_q15) {
    // P-слагаемое
    q31_t p_term = (q31_t)ctx->kp * (q31_t)error_q15; // Q15*Q15 = Q30

    // I-слагаемое: накопление
    q31_t i_delta = (q31_t)ctx->ki * (q31_t)error_q15; // Q30
    ctx->integrator = q31_sat_add(ctx->integrator, i_delta);

    // Anti-windup: clamp интегратора
    q31_t i_limit_q31 = (q31_t)ctx->i_limit << 16; // Q15 → Q31
    if (ctx->integrator > i_limit_q31)       ctx->integrator = i_limit_q31;
    else if (ctx->integrator < -i_limit_q31) ctx->integrator = -i_limit_q31;

    // Сумма P + I (оба в Q30)
    q31_t output_q30 = p_term + ctx->integrator;

    // Приведение к Q15 с насыщением
    q31_t output_q15_ext = (output_q30 + 0x4000) >> 15; // округление
    if (output_q15_ext > 0x7FFF)       output_q15_ext = 0x7FFF;
    else if (output_q15_ext < -0x8000) output_q15_ext = -0x8000;

    q15_t out = (q15_t)output_q15_ext;

    // Clamp к допустимому диапазону управления
    if (out > ctx->out_max)       out = ctx->out_max;
    else if (out < ctx->out_min)  out = ctx->out_min;

    return out;
}
```

**Настройка коэффициентов:** переводите из float на этапе инициализации (один раз, не в цикле):

```c
void pi_init(pi_q15_t *ctx, float kp_float, float ki_float, float dt) {
    // ki уже включает dt!
    ctx->kp = (q15_t)(kp_float * 32767.0f);
    ctx->ki = (q15_t)(ki_float * dt * 32767.0f);
    ctx->integrator = 0;
    ctx->i_limit = (q15_t)(0.8f * 32767.0f); // 80%
    ctx->out_min = 0;          // для уровня в баке: 0 = клапан закрыт
    ctx->out_max = 0x7FFF;     // 100% = полностью открыт
}
```

