pairs.response_b:
# ПИ-регулятор на Q15 для STM32F030C8 (Cortex-M0)

Бюджет 1000 мкс, текущее 1340 мкс — переход на целочисленную арифметику обоснован. На M0 без FPU `__aeabi_fmul` это ~70+ тактов против 1 такта `smull`. Ниже ответы по трём пунктам.

---

## 1. Умножение Q15 и переполнение

**Q15:** 1 знаковый бит + 15 дробных. Диапазон: [-1.0, +0.99997]. Представление: `int16_t`, где 1.0 = 0x7FFF, -1.0 = 0x8000.

### Умножение

Два Q15 дают Q30. На Cortex-M0 есть инструкция `SMULL` (32×32→64 за 1 такт), но нет `SMLAL` с насыщением в 16 бит напрямую. Алгоритм:

```c
// Базовое умножение Q15 × Q15 → Q15
static inline int16_t q15_mul(int16_t a, int16_t b) {
    // Промоция до int32_t обязательна!
    int32_t result = ((int32_t)a * (int32_t)b) >> 15;

    // Насыщение к диапазону int16_t
    if (result > 32767)  result = 32767;
    if (result < -32768) result = -32768;

    return (int16_t)result;
}
```

**Почему не просто `(a*b)>>15`:** при `a=0x8000, b=0x8000` результат `0x40000000 >> 15 = 0x8000` — это -1.0, что корректно. Но промежуточное произведение `-32768 * -32768 = 1073741824` требует 31 бит + знак → **обязательно `int32_t`**.

### Нужен ли насыщающий сумматор?

**Да, критически.** Интегратор — это аккумулятор, который суммирует на каждом такте. Без насыщения он улетит в wrap-around за несколько периодов при ненулевой ошибке.

```c
// Насыщающее сложение для интегратора (работает в int32_t!)
static inline int32_t sat_add_32(int32_t acc, int32_t val) {
    int32_t result = acc + val;
    // Проверка переполнения через знаки операндов
    if (((acc ^ val) >= 0) && ((acc ^ result) < 0)) {
        result = (acc >= 0) ? INT32_MAX : INT32_MIN;
    }
    return result;
}
```

**Важно:** интегратор ведите в `int32_t` (Q31 или Q15.16), а не в `int16_t`. Сужайте до Q15 только на выходе при формировании управляющего воздействия. Это даёт запас по динамике.

---

## 2. Масштабирование уставки 0..1000 в Q15

Уставка 0..1000 — это физический диапазон (например, уровень в мм). Q15 работает в нормализованных единицах [-1.0, +1.0] или [0, +1.0] для беззнакового.

### Шаг 1: Нормализация входа

Выберите масштабный коэффициент. Если уставка 0..1000, а максимальное значение датчика тоже 1000:

```c
// Перевод из физического диапазона в Q15
// u_n = u_phys / U_MAX, затем в Q15
#define U_MAX 1000

static inline int16_t phys_to_q15(int32_t phys_val) {
    // phys_val: 0..1000 → Q15: 0..32767
    // Формула: q15 = (phys_val * 32767) / U_MAX
    int32_t q = (phys_val * 32767) / U_MAX;
    if (q > 32767)  q = 32767;
    if (q < -32767) q = -32767;
    return (int16_t)q;
}
```

Эту конверсию делайте **один раз** при получении нового задания/измерения, а не в цикле 1 кГц.

### Шаг 2: Коэффициенты регулятора

Классический ПИ в позиционной форме:
```
u[k] = Kp * e[k] + Ki * Ts * Σe[j]
```

В Q15 коэффициенты `Kp` и `Ki*Ts` должны быть < 1.0. Если ваш `Kp = 2.5` в float — это проблема для Q15.

**Решение — вынос множителя степени двойки:**

```c
// Kp_real = 2.5 → представляем как Kp_q15 * 2^shift
// 2.5 = 0.625 * 4 = 0.625 * 2^2
// Kp_q15 = 0.625 * 32767 = 20480
#define KP_Q15   20480   // 0.625 в Q15
#define KP_SHIFT 2       // дополнительная степень двойки

#define KI_Q15   1638    // Ki*Ts нормализованный
#define KI_SHIFT 0
```

Применение:
```c
int32_t p_term = ((int32_t)KP_Q15 * error_q15) >> 15;
p_term <<= KP_SHIFT;  // сдвиг после умножения
```

### Шаг 3: Защита интегратора от windup

Это **главная причина** вылетов за диапазон, а не формат Q15 сам по себе.

```c
#define INTEGRATOR_MAX  (32767 * 4)   // запас в int32_t
#define INTEGRATOR_MIN  (-32767 * 4)

// В цикле 1 кГц:
int32_t integrator_raw = (int32_t)KI_Q15 * error_q15;
integrator_raw >>= 15;

int32_t new_integrator = sat_add_32(integrator_state, integrator_raw);

// Anti-windup: стопорим интегратор, если выход уже в насыщении
if (output_saturated) {
    // Не обновляем интегратор, если ошибка того же знака
    if ((error_q15 > 0 && integrator_state > 0) ||
        (error_q15 < 0 && integrator_state < 0)) {
        new_integrator = integrator_state; // откат
    }
}

// Жёсткие пределы
if (new_integrator > INTEGRATOR_MAX) new_integrator = INTEGRATOR_MAX;
if (new_integrator < INTEGRATOR_MIN) new_integrator = INTEGRATOR_MIN;

integrator_state = new_integrator;
```

### Полный цикл ПИ в Q15

```c
typedef struct {
    int16_t kp_q15;
    int16_t ki_q15;
    uint8_t kp_shift;
    uint8_t ki_shift;
    int32_t integrator;     // Q15, но в int32_t для запаса
    int16_t out_min;        // предел выхода в Q15
    int16_t out_max;
} pi_q15_t;

int16_t pi_regulate_q15(pi_q15_t *pi, int16_t setpoint_q15, int16_t measured_q15) {
    // Ошибка в Q15 (вычитание не переполняется при одинаковом диапазоне)
    int32_t err = (int32_t)setpoint_q15 - (int32_t)measured_q15;
    if (err > 32767)  err = 32767;
    if (err < -32767) err = -32767;
    int16_t error_q15 = (int16_t)err;

    // P-член
    int32_t p_term = ((int32_t)pi->kp_q15 * error_q15) >> 15;
    p_term <<= pi->kp_shift;

    // I-член (интегратор в int32_t)
    int32_t i_delta = ((int32_t)pi->ki_q15 * error_q15) >> 15;
    i_delta <<= pi->ki_shift;
    pi->integrator = sat_add_32(pi->integrator, i_delta);

    // Anti-windup clamp
    if (pi->integrator > INTEGRATOR_MAX) pi->integrator = INTEGRATOR_MAX;
    if (pi->integrator < INTEGRATOR_MIN) pi->integrator = INTEGRATOR_MIN;

    // Сумма
    int32_t output = p_term + (pi->integrator >> 0); // integrator уже в нужном масштабе

    // Насыщение выхода
    int16_t out_sat = 0;
    if (output > pi->out_max)      { out_sat = pi->out_max; }
    else if (output < pi->out_min) { out_sat = pi->out_min; }
    else                           { out_sat = (int16_t)output; }

    return out_sat;
}
```

**Оценка производительности:** на M0 `SMULL` = 1 такт, сдвиги и ветвления = ~3-5 тактов. Весь цикл ПИ в Q15 займёт **~80-120 тактов** вместо 64320. Запас огромный.

---

## 3. Верификация на железе

### A. Параллельный прогон (float vs Q15) — первый шаг

Не удаляйте float сразу. Сделайте два регулятора, работающих параллельно:

```c
// В обработчике таймера 1 кГц:
float_out  = pi_regulate_float(sp, meas);
q15_out    = pi_regulate_q15(&pi, sp_q15, meas_q15);

// Логировать разницу
delta = abs(float_out_normalized - q15_out_normalized);
log_buffer[idx++] = delta;
```

**Критерий:** расхождение между float и Q15 выходами должно быть ≤ 1 LSB целевого ЦАП/ШИМ. Если ШИМ 12-бит (0..4095), допустимо ±1..2 единицы.

### B. DWT->CYCCNT замер (уже используете)

```c
DWT->CYCCNT = 0;
pi_regulate_q15(...);
uint32_t cycles = DWT->CYCCNT;
```

Замерьте худший случай (не медиану!), потому что ветвления насыщения добавляют такты. На M0 предсказатель переходов примитивный — промах по branch penalty = 1-3 такта.

### C. Ступенчатый тест с осциллографом

1. Подайте ступеньку уставки (0 → 500 → 1000).
2. Выведите на DAC/PWM оба сигнала (float и Q15) через разные каналы.
3. Осциллограф: сравните время нарастания, перерегулирование, установившуюся ошибку.
4. **Проверьте отсутствие limit-cycling** — мелкого дрожания около уставки из-за квантования Q15. Если есть — добавьте 1 бит дробной части в интегратор (используйте Q16.15 внутри, Q15 снаружи).

### D. Краевые условия (обязательно)

| Тест | Что проверяет |
|------|---------------|
| Уставка = 0, измерение = 1000 | Максимальная отрицательная ошибка, насыщение вниз |
| Уставка = 1000, измерение = 0 | Максимальная положительная ошибка, windup |
| Быстрое переключение 0→1000→0 | Anti-windup, скорость сброса интегратора |
| Измерение = уставка (e=0) | Нет дрейфа из-за ошибок округления |
| Отключить датчик (обрыв) | Поведение при garbage input |

### E. Контроль переполнения через ITM/SWO

На STM32F030 SWO доступен через PA10 (SWV). Вставьте assert-точки:

```c
// Внутренний контроль, не влияет на timing в release
#ifdef DEBUG_Q15
if (pi->integrator > INTEGRATOR_MAX || pi->integrator < INTEGRATOR_MIN) {
    ITM_SendChar('!'); // маркер переполнения в SWV
}
#endif
```

### F. Unit-тесты на хосте (до заливки)

Скомпилируйте ту же функцию под x86, прогоните через те же входные данные, что были записаны с железа (дамп `setpoint[]`, `measured[]`). Сравните выходные массивы. Это ловит 90% ошибок масштабирования до первого подключения осциллографа.

---

## Резюме

| Аспект | Решение |
|--------|---------|
| Умножение | `(int32_t)a * b >> 15` + насыщение к int16 |
| Интегратор | Хранить в `int32_t`, насыщающий сумматор обязателен |
| Масштаб 0..1000 | `val * 32767 / 1000` один раз при входе |
| Kp > 1.0 | Вынос степени двойки: `Kp_q15 * 2^shift` |
| Windup | Clamp интегратора + conditional integration |
| Проверка | Параллельный прогон → DWT worst-case → ступенька на осциллографе → краевые условия |

